 <div class="hud hidden" id="hud"><div class="stage panel"><b id="st-no">1</b><small id="st-name"></small></div><div class="score panel"><b id="score">0</b><small id="combo"></small></div><div class="right"><span class="lives panel" id="lives"></span><button class="icon-btn" id="pause-btn" aria-label="일시정지"><i class="kit-icon kit-pause"></i></button></div><div class="ups" id="ups"></div></div>
